/**
 * Build the INSERT SQL column list and values for a line item based on its type.
 */
function buildLineItemInsert(item: CartLineItem & { __lineItemId: string; __saleId: string; __lineTotalNet: number; __lineTotalVat: number; __lineTotalGross: number }, now: number): { sql: string; params: unknown[] } {
  const baseColumns = 'id, sale_id, line_type, description, quantity, unit_price_net, vat_rate_id, discount_percent, line_total_net, line_total_vat, line_total_gross'

  if (item.lineType === 'part') {
    const partItem = item as Extract<CartLineItem, { lineType: 'part' }>
    return {
      sql: `INSERT INTO sale_line_items (${baseColumns}, part_id, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      params: [
        item.__lineItemId,
        item.__saleId,
        item.lineType,
        item.description,
        item.quantity,
        item.unitPriceNet,
        item.vatRateId,
        partItem.discountPercent ?? null,
        item.__lineTotalNet,
        item.__lineTotalVat,
        item.__lineTotalGross,
        partItem.partId,
        now,
      ]
    }
  }

  if (item.lineType === 'labor') {
    const laborItem = item as Extract<CartLineItem, { lineType: 'labor' }>
    return {
      sql: `INSERT INTO sale_line_items (${baseColumns}, labor_service_id, minutes_worked, hourly_rate_snapshot, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      params: [
        item.__lineItemId,
        item.__saleId,
        item.lineType,
        item.description,
        item.quantity,
        item.unitPriceNet,
        item.vatRateId,
        laborItem.discountPercent ?? null,
        item.__lineTotalNet,
        item.__lineTotalVat,
        item.__lineTotalGross,
        laborItem.laborServiceId ?? null,
        laborItem.minutesWorked ?? null,
        laborItem.hourlyRateSnapshot ?? null,
        now,
      ]
    }
  }

  // bicycle
  const bicycleItem = item as Extract<CartLineItem, { lineType: 'bicycle' }>
  return {
    sql: `INSERT INTO sale_line_items (${baseColumns}, bicycle_id, bicycle_brand, bicycle_model, bicycle_year, bicycle_color, bicycle_frame_size, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    params: [
      item.__lineItemId,
      item.__saleId,
      item.lineType,
      item.description,
      item.quantity,
      item.unitPriceNet,
      item.vatRateId,
      bicycleItem.discountPercent ?? null,
      item.__lineTotalNet,
      item.__lineTotalVat,
      item.__lineTotalGross,
      bicycleItem.bicycleId ?? null,
      bicycleItem.bicycleBrand ?? null,
      bicycleItem.bicycleModel ?? null,
      bicycleItem.bicycleYear ?? null,
      bicycleItem.bicycleColor ?? null,
      bicycleItem.bicycleFrameSize ?? null,
      now,
    ]
  }
}

// ============================================================================
// Public API
// ============================================================================

/**
 * Create a direct sale atomically in a single database transaction.
 *
 * Flow: validate input → check stock (parts only) → get sequence number → insert sale header
 *       → insert line items → insert payment → insert allocation → insert stock movements (parts only)
 * All-or-nothing: any failure rolls back everything.
 *
 * @param rawInput — Unvalidated input object (will be validated via Zod)
 * @returns Sale result with created entities
 */
export async function createDirectSale(rawInput: unknown): Promise<SaleResult> {
  // Validate input via Zod schema
  const parsed = createDirectSaleInputSchema.safeParse(rawInput)
  if (!parsed.success) {
    throw new Error(`Invalid sale input: ${parsed.error.message}`)
  }

  const input = parsed.data as CreateDirectSaleInput

  // ---------------------------------------------------------------------------
  // Step 1: Validate stock availability for part-type line items only
  // Labor and bicycle line items bypass stock check.
  // ---------------------------------------------------------------------------
  const partItems = input.lineItems.filter((item): item is Extract<CartLineItem, { lineType: 'part' }> => item.lineType === 'part')

  const stockRequests = partItems.map((item) => ({
    partId: item.partId,
    requestedQuantity: item.quantity
  }))

  const stockResult = await validateStockAvailability(stockRequests)
  if (!stockResult.valid) {
    throw new InsufficientStockError(stockResult.shortfalls)
  }

  // ---------------------------------------------------------------------------
  // Step 2: Get sale number from sequence table (atomic increment)
  // ---------------------------------------------------------------------------
  const saleNumberSeq = await getNextValue('sale')
  const saleNumber = `SA-${String(saleNumberSeq).padStart(4, '0')}`

  // ---------------------------------------------------------------------------
  // Step 3: Fetch VAT rates needed for line item calculations
  // ---------------------------------------------------------------------------
  const allVatRates = await db.select({ id: vatRates.id, rate: vatRates.rate }).from(vatRates)
  const vatRatesMap = new Map<string, number>()
  for (const row of allVatRates) {
    vatRatesMap.set(row.id, Number(row.rate))
  }

  // ---------------------------------------------------------------------------
  // Step 4: Compute line item totals using shared pricing lib (uniform across types)
  // ---------------------------------------------------------------------------
  const saleId = crypto.randomUUID()
  const paymentId = crypto.randomUUID()

  // Augment each line item with computed totals and internal IDs for INSERT
  type AugmentedLineItem = CartLineItem & {
    __lineItemId: string
    __saleId: string
    __lineTotalNet: number
    __lineTotalVat: number
    __lineTotalGross: number
  }

  const lineItemsData: AugmentedLineItem[] = input.lineItems.map((item) => {
    const vatRateBps = vatRatesMap.get(item.vatRateId) ?? 0
    const totals = computeLineTotals(
      item.unitPriceNet,
      item.quantity,
      (item as PartLineItemInput | LaborLineItemInput | BicycleLineItemInput).discountPercent ?? null,
      vatRateBps
    )

    return {
      ...item,
      __lineItemId: crypto.randomUUID(),
      __saleId: saleId,
      __lineTotalNet: totals.net,
      __lineTotalVat: totals.vat,
      __lineTotalGross: totals.gross,
    }
  })

  const subtotalNet = lineItemsData.reduce((sum, item) => sum + item.__lineTotalNet, 0)
  const vatTotal = lineItemsData.reduce((sum, item) => sum + item.__lineTotalVat, 0)
  const totalGross = subtotalNet + vatTotal

  // ---------------------------------------------------------------------------
  // Step 5: Execute single transaction — all inserts or nothing
  // ---------------------------------------------------------------------------
  const client = sqliteDb as Database.Database
  const run = (sqlStr: string, params?: unknown[]) => {
    return client.prepare(sqlStr).run(...(params ?? []))
  }

  try {
    // Begin transaction
    run('BEGIN TRANSACTION')

    // Insert sale header
    run(
      'INSERT INTO sales (id, sale_number, customer_id, source_type, source_id, status, subtotal_net, vat_total, total_gross, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
      [saleId, saleNumber, input.customerId ?? null, 'direct_sale', null, 'completed', subtotalNet, vatTotal, totalGross, Date.now()]
    )

    const now = Date.now()

    // Insert line items (per-type column sets)
    for (const item of lineItemsData) {
      const insert = buildLineItemInsert(item, now)
      run(insert.sql, insert.params)
    }

    // Insert payment record
    run(
      'INSERT INTO payments (id, method, amount, created_at) VALUES (?, ?, ?, ?)',
      [paymentId, input.paymentMethod, totalGross, now]
    )

    // Insert payment allocation (payment → sale)
    run(
      'INSERT INTO payment_allocations (id, payment_id, target_type, target_id, allocated_amount) VALUES (?, ?, ?, ?, ?)',
      [crypto.randomUUID(), paymentId, 'sale', saleId, totalGross]
    )

    // Insert stock movements — only for part-type line items
    for (const item of partItems) {
      run(
        'INSERT INTO stock_movements (id, part_id, quantity_delta, reason, reference_type, reference_id, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)',
        [crypto.randomUUID(), item.partId, -item.quantity, 'sale', 'sale', saleId, now]
      )
    }

    // Commit transaction
    run('COMMIT')
  } catch (err) {
    // Rollback on any error
    try { run('ROLLBACK') }
    catch {}
    throw err
  }

  // ---------------------------------------------------------------------------
  // Step 6: Fetch and return created entities
  // ---------------------------------------------------------------------------
  const [createdSale] = await db.select().from(sales).where(eq(sales.id, saleId))
  const [createdPayment] = await db.select().from(payments).where(eq(payments.id, paymentId))
  const lineItemRows = await db.select().from(saleLineItems).where(eq(saleLineItems.saleId, saleId)).orderBy(asc(saleLineItems.createdAt))

  return {
    sale: createdSale!,
    payment: createdPayment!,
    lineItems: lineItemRows
  }
}

/**
 * Void a completed sale by setting its status to 'voided'.
 *
 * Does NOT reverse stock movements (per domain rule R13 — voiding accepts error risk).
 * Guards against voiding already-voided sales.
 *
 * @param saleId — ID of the sale to void
 * @returns The updated sale record
 */
export async function voidSale(saleId: string): Promise<typeof sales.$inferSelect> {
  // Check if sale exists and is not already voided
  const existing = await db.select().from(sales).where(eq(sales.id, saleId))

  if (existing.length === 0) {
    throw new SaleNotFoundError(saleId)
  }

  if (existing[0].status === 'voided') {
    throw new Error(`Sale ${saleId} is already voided`)
  }

  // Update status to voided
  const [updated] = await db
    .update(sales)
    .set({ status: 'voided' })
    .where(eq(sales.id, saleId))
    .returning()

  return updated!
}

/**
 * Find a single sale by ID.
 */
export async function findSaleById(id: string) {
  const [result] = await db.select().from(sales).where(eq(sales.id, id))
  return result ?? undefined
}

/** Options for listing sales */
export interface ListSalesOptions {
  /** Maximum number of rows to return (default: 50) */
  limit?: number
  /** Filter by customer ID — null/absent means no filter */
  customerId?: string | null
}

/**
 * List recent sales ordered by creation date (newest first).
 *
 * @param options — Filtering and pagination options
 * @returns Array of sale records sorted newest-first
 */
export async function listSales(options: ListSalesOptions = {}) {
  const { limit = 50, customerId } = options

  const whereClause = customerId ? eq(sales.customerId, customerId) : undefined

  return db
    .select()
    .from(sales)
    .where(whereClause)
    .orderBy(desc(sales.createdAt))
    .limit(limit)
}

/**
 * Get all line items for a sale, ordered by creation.
 */
export async function findLineItemsBySaleId(saleId: string) {
  return db.select().from(saleLineItems).where(eq(saleLineItems.saleId, saleId)).orderBy(asc(saleLineItems.createdAt))
}

/**
 * Get all payments for a sale (via allocations), ordered by creation.
 */
export async function findPaymentsBySaleId(saleId: string) {
  const allocations = await db.select().from(paymentAllocations).where(eq(paymentAllocations.targetId, saleId))
  if (allocations.length === 0) return []

  const paymentIds = allocations.map(a => a.paymentId)
  return db.select().from(payments).where(sql`${payments.id} IN (${sql.join(paymentIds)})`).orderBy(asc(payments.createdAt))
}

/**
 * Get all stock movements referencing a specific sale.
 */
export async function findMovementsBySaleId(saleId: string) {
  return db.select().from(stockMovements).where(eq(stockMovements.referenceId, saleId))
}

import { describe, it, expect } from 'vitest'
import { useCartStore } from '../store'

// Helper to create a fresh store for each test
function createFreshStore() {
  // Reset all state fields to initial values
  useCartStore.setState({
    lineItems: [],
    customerId: null,
    checkoutError: null,
    checkoutSuccess: null,
    isCheckingOut: false,
    subtotalNet: 0,
    vatTotal: 0,
    totalGross: 0,
    canCheckout: false,
  })
}

// ── Helper data ────────────────────────────────────────────────────

const mockPart = {
  id: 'part-001',
  barcode: '1234567890',
  name: 'Bolt M6 x 20mm',
  priceNet: 500, // €5.00 in cents
  quantityOnHand: 100,
}

const mockPart2 = {
  id: 'part-002',
  barcode: '0987654321',
  name: 'Wrench Set',
  priceNet: 1500, // €15.00 in cents
  quantityOnHand: 50,
}

const mockCustomer = {
  id: 'cust-123',
  displayName: 'John Doe',
  type: 'private' as const,
}

// ── Add Line Item ──────────────────────────────────────────────────

describe('Cart Store — addLineItem', () => {
  beforeEach(() => createFreshStore())

  it('adds a part to the cart with correct line item data', () => {
    useCartStore.getState().addLineItem(mockPart)

    const state = useCartStore.getState()
    expect(state.lineItems).toHaveLength(1)
    const item = state.lineItems[0]
    expect(item.partId).toBe(mockPart.id)
    expect(item.barcode).toBe(mockPart.barcode)
    expect(item.name).toBe(mockPart.name)
    expect(item.priceNet).toBe(mockPart.priceNet)
    expect(item.quantity).toBe(1)
    expect(item.vatRateId).toBe('vat-standard') // default VAT rate
    // Verify computed totals: 500 × 1 = 500 net, VAT = round(500 × 2100/10000) = 105, gross = 605
    expect(item.lineTotalNet).toBe(500)
    expect(item.lineTotalVat).toBe(105)
    expect(item.lineTotalGross).toBe(605)
  })

  it('adds a part with specified quantity', () => {
    useCartStore.getState().addLineItem(mockPart, 3)

    const state = useCartStore.getState()
    expect(state.lineItems[0].quantity).toBe(3)
  })

  it('increments quantity when adding same part twice', () => {
    useCartStore.getState().addLineItem(mockPart)
    useCartStore.getState().addLineItem(mockPart, 2)

    const state = useCartStore.getState()
    expect(state.lineItems).toHaveLength(1) // still one line item
    expect(state.lineItems[0].quantity).toBe(3) // 1 + 2
  })

  it('adds different parts as separate line items', () => {
    useCartStore.getState().addLineItem(mockPart)
    useCartStore.getState().addLineItem(mockPart2)

    const state = useCartStore.getState()
    expect(state.lineItems).toHaveLength(2)
  })
})

// ── Remove Line Item ───────────────────────────────────────────────

describe('Cart Store — removeLineItem', () => {
  beforeEach(() => createFreshStore())

