// Helper to create a fresh store for each test
function createFreshStore() {
  // Reset all state fields to initial values
  useCartStore.setState({
    lineItems: [],
    customerId: null,
    checkoutError: null,
    checkoutSuccess: null,
    isCheckingOut: false,
    subtotalNet: 0,
    vatTotal: 0,
    totalGross: 0,
    canCheckout: false,
